mkdir -p bin src test && cat > package.json <<'EOF'
{
  "name": "color-cli",
  "version": "0.1.0",
  "description": "A Node.js CLI that only prints colored output when the terminal supports it",
  "type": "module",
  "bin": {
    "color-cli": "./bin/cli.js"
  },
  "files": [
    "bin",
    "src"
  ],
  "scripts": {
    "start": "node bin/cli.js",
    "test": "node --test"
  },
  "engines": {
    "node": ">=18"
  },
  "license": "MIT"
}
EOF
cat > .gitignore <<'EOF'
node_modules/
*.log
EOF
cat > src/supports-color.js <<'EOF'
/**
 * Decide whether `stream` should receive ANSI color codes.
 *
 * Precedence (first match wins):
 *   1. CLI flags:   --no-color / --color=never  -> off
 *                   --color / --color=always    -> on
 *   2. NO_COLOR (any non-empty value, see https://no-color.org) -> off
 *      NODE_DISABLE_COLORS (any non-empty value)                -> off
 *   3. FORCE_COLOR: "0" or "false" -> off, any other value -> on
 *   4. Stream is not a TTY (piped / redirected to a file) -> off
 *   5. TERM=dumb -> off
 *   6. Otherwise defer to Node's own terminal capability check
 *      (tty.WriteStream#hasColors, which inspects TERM, COLORTERM, CI, OS).
 *
 * `env` and `argv` are injectable so the logic is easy to test.
 */
export function supportsColor(
  stream = process.stdout,
  { env = process.env, argv = process.argv } = {},
) {
  const flag = colorFlag(argv);
  if (flag !== undefined) return flag;

  if (env.NO_COLOR || env.NODE_DISABLE_COLORS) return false;

  if (env.FORCE_COLOR !== undefined) {
    return !['0', 'false'].includes(env.FORCE_COLOR.toLowerCase());
  }

  if (!stream || !stream.isTTY) return false;

  if (env.TERM === 'dumb') return false;

  if (typeof stream.hasColors === 'function') {
    return stream.hasColors(env);
  }

  return true;
}

function colorFlag(argv) {
  let result;
  // Last flag wins, so `--color --no-color` disables colors.
  for (const arg of argv) {
    if (arg === '--no-color' || arg === '--color=never') result = false;
    else if (arg === '--color' || arg === '--color=always') result = true;
  }
  return result;
}
EOF
cat > src/colors.js <<'EOF'
import { supportsColor } from './supports-color.js';

const STYLES = {
  bold: [1, 22],
  dim: [2, 22],
  red: [31, 39],
  green: [32, 39],
  yellow: [33, 39],
  blue: [34, 39],
  magenta: [35, 39],
  cyan: [36, 39],
  gray: [90, 39],
};

/**
 * Build a set of style functions. When `enabled` is false every function
 * returns its input unchanged, so callers never need to branch themselves.
 */
export function createColors(enabled) {
  const colors = { enabled };
  for (const [name, [open, close]] of Object.entries(STYLES)) {
    colors[name] = enabled
      ? (text) => `\x1b[${open}m${text}\x1b[${close}m`
      : (text) => String(text);
  }
  return colors;
}

// Detected separately: stdout may be piped while stderr is still a terminal.
export const stdoutColors = createColors(supportsColor(process.stdout));
export const stderrColors = createColors(supportsColor(process.stderr));
EOF
cat > bin/cli.js <<'EOF'
#!/usr/bin/env node
import { stdoutColors as c, stderrColors as e } from '../src/colors.js';

const args = process.argv.slice(2).filter((a) => !a.startsWith('--color') && a !== '--no-color');

if (args.includes('--help') || args.includes('-h')) {
  console.log(`${c.bold('Usage:')} color-cli [options]

${c.bold('Options:')}
  --color, --color=always   Force colored output
  --no-color, --color=never Disable colored output
  -h, --help                Show this help

Colors are also controlled by the NO_COLOR and FORCE_COLOR env vars.`);
  process.exit(0);
}

console.log(c.green('✔ Success:'), 'everything worked');
console.log(c.yellow('⚠ Warning:'), 'this is a warning');
console.log(c.cyan('ℹ Info:'), `colors are ${c.enabled ? c.bold('enabled') : 'disabled'} on stdout`);
console.error(e.red('✖ Error:'), 'this goes to stderr');
EOF
chmod +x bin/cli.js
cat > test/supports-color.test.js <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { supportsColor } from '../src/supports-color.js';
import { createColors } from '../src/colors.js';

const tty = (hasColors = true) => ({ isTTY: true, hasColors: () => hasColors });
const pipe = { isTTY: false };
const check = (stream, env = {}, argv = []) => supportsColor(stream, { env, argv });

test('enabled on a color-capable TTY', () => {
  assert.equal(check(tty()), true);
});

test('disabled when output is not a TTY', () => {
  assert.equal(check(pipe), false);
});

test('disabled when the terminal reports no color support', () => {
  assert.equal(check(tty(false)), false);
});

test('disabled for TERM=dumb', () => {
  assert.equal(check(tty(), { TERM: 'dumb' }), false);
});

test('NO_COLOR disables colors, but only when non-empty', () => {
  assert.equal(check(tty(), { NO_COLOR: '1' }), false);
  assert.equal(check(tty(), { NO_COLOR: '' }), true);
});

test('NODE_DISABLE_COLORS disables colors', () => {
  assert.equal(check(tty(), { NODE_DISABLE_COLORS: '1' }), false);
});

test('FORCE_COLOR overrides TTY detection', () => {
  assert.equal(check(pipe, { FORCE_COLOR: '1' }), true);
  assert.equal(check(pipe, { FORCE_COLOR: '' }), true);
  assert.equal(check(tty(), { FORCE_COLOR: '0' }), false);
  assert.equal(check(tty(), { FORCE_COLOR: 'false' }), false);
});

test('NO_COLOR beats FORCE_COLOR', () => {
  assert.equal(check(tty(), { NO_COLOR: '1', FORCE_COLOR: '1' }), false);
});

test('CLI flags beat environment variables, last flag wins', () => {
  assert.equal(check(pipe, { NO_COLOR: '1' }, ['--color']), true);
  assert.equal(check(tty(), { FORCE_COLOR: '1' }, ['--no-color']), false);
  assert.equal(check(tty(), {}, ['--color=never']), false);
  assert.equal(check(pipe, {}, ['--color=always']), true);
  assert.equal(check(pipe, {}, ['--no-color', '--color']), true);
});

test('createColors wraps text only when enabled', () => {
  assert.equal(createColors(true).red('x'), '\x1b[31mx\x1b[39m');
  assert.equal(createColors(false).red('x'), 'x');
});
EOF
npm test 2>&1 | tail -12
echo "--- piped:"; node bin/cli.js | cat -v
echo "--- forced:"; FORCE_COLOR=1 node bin/cli.js 2>/dev/null | cat -v
echo "--- flag:"; node bin/cli.js --color 2>/dev/null | cat -v

